    <div class="count" id="count" aria-live="polite"></div>
  </div>
</main>

<script>
  const input  = document.getElementById('input');
  const output = document.getElementById('output');
  const copyBtn = document.getElementById('copy');
  const count  = document.getElementById('count');

  const ENTITIES = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  };

  // Single pass, so already-produced entities are never double-escaped
  const escapeHtml = str => str.replace(/[&<>"']/g, ch => ENTITIES[ch]);

  input.addEventListener('input', () => {
    output.value = escapeHtml(input.value);
    copyBtn.disabled = output.value === '';
    count.textContent = output.value
      ? `${input.value.length} → ${output.value.length} characters`
      : '';
  });

  let resetTimer;

  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(output.value);
    } catch {
      // Fallback for older browsers / non-secure contexts
      output.focus();
      output.select();
      output.setSelectionRange(0, output.value.length);
      document.execCommand('copy');
      output.setSelectionRange(0, 0);
      output.blur();
    }

    copyBtn.textContent = 'Copied!';
    copyBtn.classList.add('copied');

    clearTimeout(resetTimer);
    resetTimer = setTimeout(() => {
      copyBtn.textContent = 'Copy to clipboard';
      copyBtn.classList.remove('copied');
    }, 1500);
  });
</script>
</body>
</html>
```

- **Escaping:** `&` → `&amp;`, `<` → `&lt;`, `>` → `&gt;`, `"` → `&quot;`, `'` → `&#39;`. It's a single regex pass, so `&` is never double-escaped.
- **Copy button:** it shows "Copied!" for 1.5s, then reverts. Clicking again during that window restarts the timer. It uses the Clipboard API with an `execCommand` fallback for older browsers and non-HTTPS contexts.
- **Mobile:**
  - The viewport meta tag is set.
  - Textareas use 16px text so iOS doesn't zoom on focus.
  - The button is full-width with a 44px tap target on small screens.
  - The layout stacks vertically.
- **Extras:** it follows the system dark mode, and the button is disabled while the input is empty.

