import OpenAI from "openai";
import "./style.css";

const MODEL = "gpt-4"; // change here if you want a newer model
const KEY_STORAGE = "openai_api_key";

const $ = (id) => document.getElementById(id);
const threadEl = $("thread");
const messageEl = $("message");
const translateBtn = $("translate-btn");
const outputSection = $("output-section");
const outputEl = $("output");
const copyBtn = $("copy-btn");
const errorEl = $("error");
const settingsDialog = $("settings-dialog");
const apiKeyInput = $("api-key");

// ---------- Settings ----------
$("settings-btn").addEventListener("click", () => {
  apiKeyInput.value = localStorage.getItem(KEY_STORAGE) || "";
  settingsDialog.showModal();
});

$("save-key-btn").addEventListener("click", () => {
  localStorage.setItem(KEY_STORAGE, apiKeyInput.value.trim());
});

// ---------- Helpers ----------
function showError(msg) {
  errorEl.textContent = msg;
  errorEl.hidden = !msg;
}

function buildPrompt(thread, message) {
  return `Here's a text message thread in Japanese:

<thread>
${thread}
</thread>

Now translate my new message below into Japanese. Make it sound natural in the flow of this conversation, matching the tone, politeness level, and style (e.g. casual vs. polite, emoji usage) of the thread. Don't translate word for word; translate the general meaning.

<my_message>
${message}
</my_message>

Reply with only the Japanese text of the message, with no explanation, quotes, or romaji.`;
}

// ---------- Translate ----------
translateBtn.addEventListener("click", async () => {
  showError("");

  const apiKey = localStorage.getItem(KEY_STORAGE);
  if (!apiKey) {
    showError("Please add your OpenAI API key in Settings first.");
    return;
  }

  const thread = threadEl.value.trim();
  const message = messageEl.value.trim();
  if (!message) {
    showError("Write the message you want to send first.");
    return;
  }

  translateBtn.disabled = true;
  translateBtn.textContent = "Translating...";

  try {
    const client = new OpenAI({ apiKey, dangerouslyAllowBrowser: true });
    const completion = await client.chat.completions.create({
      model: MODEL,
      messages: [
        {
          role: "system",
          content:
            "You are an expert English-to-Japanese translator who writes natural-sounding text messages.",
        },
        { role: "user", content: buildPrompt(thread || "(no previous messages)", message) },
      ],
    });

    outputEl.textContent = completion.choices[0].message.content.trim();
    outputSection.hidden = false;
  } catch (err) {
    console.error(err);
    showError(err?.message || "Something went wrong.");
  } finally {
    translateBtn.disabled = false;
    translateBtn.textContent = "Translate";
  }
});

// ---------- Copy ----------
copyBtn.addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText(outputEl.textContent);
    copyBtn.textContent = "Copied!";
  } catch {
    copyBtn.textContent = "Copy failed";
  }
  setTimeout(() => (copyBtn.textContent = "Copy"), 1500);
});
```

