  const previewCard = $('previewCard'), preview = $('preview');
  const resultCard = $('resultCard'), resultBody = $('resultBody');

  let currentUrl = null;

  /* ---------- Input handling ---------- */

  document.addEventListener('paste', e => {
    const items = e.clipboardData && e.clipboardData.items;
    if (!items) return;
