      }
    }
    showError('The clipboard doesn\'t contain an image.');
  });

  pasteBtn.addEventListener('click', async () => {
    if (!navigator.clipboard || !navigator.clipboard.read) {
      showError('Your browser doesn\'t allow button-based pasting here. Press Ctrl/⌘+V instead.');
      return;
    }
    try {
      const items = await navigator.clipboard.read();
      for (const item of items) {
        const type = item.types.find(t => t.startsWith('image/'));
        if (type) return handleBlob(await item.getType(type));
      }
      showError('The clipboard doesn\'t contain an image.');
    } catch (err) {
      showError('Clipboard access was blocked. Press Ctrl/⌘+V instead.');
    }
