    previewCard.classList.add('hidden');
    resultCard.classList.add('hidden');
    clearBtn.classList.add('hidden');
    resultBody.replaceChildren();
  }

  /* ---------- Decoding ---------- */

  async function handleBlob(blob) {
    reset();
    currentUrl = URL.createObjectURL(blob);
    preview.src = currentUrl;
    previewCard.classList.remove('hidden');
    clearBtn.classList.remove('hidden');

    try {
      const img = await loadImage(currentUrl);
      const code = decode(img);
      if (code) showResult(code.data);
      else showError('No QR code found in that image. Try a sharper or less cropped screenshot.');
    } catch (err) {
      showError('Could not read that image.');
    }
  }

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = src;
    });
  }

  function decode(img) {
    if (typeof jsQR !== 'function') throw new Error('jsQR failed to load');
    const scales = [1, 0.5, 0.25, 2, 0.75];
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d', { willReadFrequently: true });

    for (const s of scales) {
      const w = Math.round(img.naturalWidth * s);
      const h = Math.round(img.naturalHeight * s);
      if (w < 40 || h < 40 || w > 4000 || h > 4000) continue;

      // Add a white quiet zone so tightly cropped codes still decode
      const pad = Math.round(Math.max(w, h) * 0.1);
      canvas.width = w + pad * 2;
      canvas.height = h + pad * 2;
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, pad, pad, w, h);

      const data = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const code = jsQR(data.data, data.width, data.height, { inversionAttempts: 'attemptBoth' });
      if (code) return code;
    }
    return null;
  }

  /* ---------- Interpretation ---------- */

  const SAFE_PROTOCOLS = ['http:', 'https:', 'mailto:', 'tel:', 'sms:', 'smsto:'];

  function toSafeUrl(text) {
    const t = text.trim();
    if (!t || /\s/.test(t)) return null;
    try {
      const u = new URL(t);
      if (SAFE_PROTOCOLS.includes(u.protocol)) return u.href;
      return null;
    } catch (_) {}
    // Bare domains like "www.example.com" or "example.com/path"
    if (/^(www\.)?[a-z0-9-]+(\.[a-z0-9-]+)+(:\d+)?([/?#]\S*)?$/i.test(t)) {
      try { return new URL('https://' + t).href; } catch (_) {}
    }
    return null;
  }

  function parseWifi(text) {
    const body = text.slice(5);
    const out = {};
    let key = '', val = '', inVal = false, esc = false;
    const commit = () => { if (key) out[key] = val; key = ''; val = ''; inVal = false; };
    for (const ch of body) {
      if (esc) { (inVal ? (val += ch) : (key += ch)); esc = false; }
      else if (ch === '\\') esc = true;
      else if (ch === ':' && !inVal) inVal = true;
      else if (ch === ';') commit();
      else (inVal ? (val += ch) : (key += ch));
    }
    commit();
    return out;
  }

  function classify(text) {
    const t = text.trim();
    if (/^WIFI:/i.test(t)) {
      const w = parseWifi(t);
      return { type: 'Wi-Fi network', fields: [
        ['Network (SSID)', w.S], ['Password', w.P],
        ['Security', w.T], ['Hidden', w.H]
