        ['Name', get(/^FN:(.*)$/im)],
        ['Phone', get(/^TEL[^:]*:(.*)$/im)],
        ['Email', get(/^EMAIL[^:]*:(.*)$/im)],
        ['Organization', get(/^ORG:(.*)$/im)]
      ] };
    }
    if (/^geo:/i.test(t)) return { type: 'Location', fields: [['Coordinates', t.slice(4)]] };
    if (/^mailto:/i.test(t)) return { type: 'Email', fields: [] };
    if (/^tel:/i.test(t)) return { type: 'Phone number', fields: [] };
    if (/^smsto?:/i.test(t)) return { type: 'SMS', fields: [] };
    if (/^otpauth:/i.test(t)) return { type: 'One-time password (2FA) setup', fields: [] };
    if (toSafeUrl(t)) return { type: 'Link', fields: [] };
    return { type: 'Text', fields: [] };
  }

  /* ---------- Rendering ---------- */

  function el(tag, props = {}, ...children) {
    const node = document.createElement(tag);
    Object.assign(node, props);
    node.append(...children);
    return node;
  }

  function showResult(text) {
    const info = classify(text);
    const url = toSafeUrl(text);
    const nodes = [];

    nodes.push(el('p', { className: 'status-ok' }, '✓ QR code decoded'));
    nodes.push(el('span', { className: 'badge' }, info.type));

    if (url) {
      const a = el('a', { className: 'result-link', href: url, target: '_blank', rel: 'noopener noreferrer' }, url);
      nodes.push(el('div', { className: 'label' }, 'Link'));
      nodes.push(el('div', {}, a));
      if (/^https?:/i.test(url)) {
        nodes.push(el('div', { className: 'warn' },
          'Only open links from sources you trust. QR codes can lead to phishing sites.'));
      }
    }

    const rows = info.fields.filter(([, v]) => v);
    if (rows.length) {
      const table = el('table', { className: 'fields' });
      rows.forEach(([k, v]) => table.append(el('tr', {}, el('td', {}, k), el('td', {}, v))));
      nodes.push(el('div', { className: 'label' }, 'Details'));
      nodes.push(table);
    }

    nodes.push(el('div', { className: 'label' }, 'Raw content'));
    nodes.push(el('pre', { id: 'raw' }, text));

    const copy = el('button', { type: 'button' }, 'Copy text');
    copy.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(text);
        copy.textContent = 'Copied!';
      } catch (_) {
        copy.textContent = 'Copy failed';
      }
      setTimeout(() => (copy.textContent = 'Copy text'), 1500);
    });
    nodes.push(el('div', { className: 'actions' }, copy));

    resultBody.replaceChildren(...nodes);
    resultCard.classList.remove('hidden');
  }

  function showError(msg) {
    resultBody.replaceChildren(el('p', { className: 'status-err' }, msg));
    resultCard.classList.remove('hidden');
  }
