    return a;
  }

  function addWarning(msg) {
    const d = document.createElement('div');
    d.className = 'warn'; d.textContent = msg;
    warnings.appendChild(d);
  }

  function addText(parent, tag, text) {
    const el = document.createElement(tag); el.textContent = text; parent.appendChild(el); return el;
  }

  function addTable(parent, rows) {
    const t = document.createElement('table');
    rows.filter(r => r[1] !== undefined && r[1] !== '').forEach(([k, v]) => {
      const tr = t.insertRow();
      tr.insertCell().textContent = k;
      tr.insertCell().textContent = v;
    });
    parent.appendChild(t);
  }

  function show(text) {
    lastRaw = text;
    result.hidden = false;
    badge.className = 'badge';
    content.replaceChildren();
    warnings.replaceChildren();
    raw.textContent = text;
    copyBtn.hidden = false;
    const t = text.trim();

    if (/^https?:\/\//i.test(t)) {
      let u = null;
      try { u = new URL(t); } catch {}
      badge.textContent = 'Web link';
      if (u) {
        content.appendChild(makeLink(u.href, t));
        addText(content, 'div', 'Goes to: ' + u.hostname).style.cssText = 'color:var(--muted);font-size:.9rem;margin-top:4px';
        if (u.protocol === 'http:') addWarning('This link is not encrypted (http, not https).');
        if (u.hostname.includes('xn--')) addWarning('This address uses internationalised characters that can imitate another site. Check it carefully.');
        if (u.username || u.password) addWarning('This link contains a username/password section, which is often used to disguise the real destination.');
      } else {
        addText(content, 'div', t);
        addWarning('This looks like a link but could not be parsed, so it was not made clickable.');
      }
    } else if (/^www\.[^\s]+\.[^\s]+$/i.test(t)) {
      badge.textContent = 'Web address';
      content.appendChild(makeLink('https://' + t, t));
      addWarning('No protocol was in the code; the link assumes https://.');
    } else if (/^mailto:/i.test(t)) {
      badge.textContent = 'Email';
      content.appendChild(makeLink(t, t.replace(/^mailto:/i, '').split('?')[0]));
    } else if (/^tel:/i.test(t)) {
      badge.textContent = 'Phone number';
      content.appendChild(makeLink(t, t.replace(/^tel:/i, '')));
    } else if (/^smsto?:/i.test(t)) {
      badge.textContent = 'SMS';
      addText(content, 'div', t.replace(/^smsto?:/i, ''));
    } else if (/^geo:/i.test(t)) {
      badge.textContent = 'Location';
      const m = t.match(/^geo:(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/i);
      if (m) content.appendChild(makeLink(`https://www.openstreetmap.org/?mlat=${m[1]}&mlon=${m[2]}#map=16/${m[1]}/${m[2]}`, `Open ${m[1]}, ${m[2]} on OpenStreetMap`));
      else addText(content, 'div', t);
    } else if (/^WIFI:/i.test(t)) {
      badge.textContent = 'Wi-Fi network';
      const w = parseWifi(t);
      addTable(content, [['Network', w.S], ['Password', w.P], ['Security', w.T], ['Hidden', w.H]]);
    } else if (/^BEGIN:VCARD/i.test(t)) {
      badge.textContent = 'Contact card (vCard)';
      const get = k => (t.match(new RegExp('^' + k + '[^:\\n]*:(.*)$', 'mi')) || [])[1]?.trim();
      addTable(content, [['Name', get('FN')], ['Phone', get('TEL')], ['Email', get('EMAIL')], ['Organisation', get('ORG')]]);
    } else {
      badge.textContent = 'Text';
      addText(content, 'div', t);
    }
  }

  function showError(msg, keepPreview) {
    result.hidden = false;
    badge.className = 'badge err';
    badge.textContent = 'Not decoded';
    content.replaceChildren();
    warnings.replaceChildren();
    addText(content, 'div', msg);
    raw.textContent = '';
    lastRaw = '';
    copyBtn.hidden = true;
    if (!keepPreview) preview.removeAttribute('src');
  }
})();
</script>
</body>
</html>
```

- **Decoding:** it uses the browser's built-in `BarcodeDetector` where available and falls back to [jsQR](https://github.com/cozmo/jsQR), loaded from cdnjs. The fallback retries at several scales, with inverted colors, and adds a white margin so tightly cropped codes still work. The image never leaves your browser.
- **Recognized types:** web links, bare `www.` addresses, email, phone, SMS, geo locations, Wi-Fi credentials and vCards. Anything else is shown as plain text. The raw payload is always shown with a copy button.
- **Safety:** only `http(s)`, `mailto:` and `tel:` become clickable, so `javascript:` and similar payloads stay as text. Links open with `noopener noreferrer`. The page warns about plain `http`, lookalike (punycode) domains and `user:pass@` tricks.
- **Limitations:** the fallback decoder needs the cdnjs script to load, and very blurry or low-contrast images may still fail to decode. Clipboard writing may be restricted in some sandboxed iframes.

