    <small>Images are decoded locally in your browser and never uploaded.</small>
    <input id="file" type="file" accept="image/*" hidden>
  </div>

  <section id="result" aria-live="polite">
    <div class="row">
      <img id="preview" alt="Pasted QR code">
      <div class="info">
        <span id="badge" class="badge"></span>
        <div id="content"></div>
        <dl id="fields" class="fields"></dl>
        <div id="link-wrap"><a id="link" target="_blank" rel="noopener noreferrer"></a></div>
        <div id="warn"></div>
        <div class="actions"><button id="copy" type="button">Copy text</button></div>
      </div>
    </div>
  </section>
</main>

<script src="https://cdnjs.cloudflare.com/ajax/libs/jsQR/1.4.0/jsQR.min.js"></script>
<script>
(() => {
  const $ = id => document.getElementById(id);
  const drop = $('drop'), fileInput = $('file'), result = $('result');
  const preview = $('preview'), badge = $('badge'), content = $('content');
  const fieldsEl = $('fields'), linkWrap = $('link-wrap'), link = $('link');
  const warn = $('warn'), copyBtn = $('copy');

  let currentText = '';

  // ---------- Input handling ----------
  document.addEventListener('paste', e => {
    const items = e.clipboardData?.items || [];
    for (const item of items) {
      if (item.type.startsWith('image/')) {
        e.preventDefault();
        handleBlob(item.getAsFile());
        return;
      }
    }
    showError('No image found on the clipboard.');
  });

  drop.addEventListener('click', () => fileInput.click());
  drop.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); }
  });
  fileInput.addEventListener('change', () => {
    if (fileInput.files[0]) handleBlob(fileInput.files[0]);
    fileInput.value = '';
  });

  ['dragenter', 'dragover'].forEach(ev =>
    drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.add('drag'); }));
  ['dragleave', 'drop'].forEach(ev =>
    drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.remove('drag'); }));
  drop.addEventListener('drop', e => {
    const f = [...e.dataTransfer.files].find(f => f.type.startsWith('image/'));
    if (f) handleBlob(f); else showError('That file is not an image.');
  });
  // Prevent browser from navigating if dropped outside the zone
  window.addEventListener('dragover', e => e.preventDefault());
  window.addEventListener('drop', e => e.preventDefault());

  copyBtn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(currentText);
      copyBtn.textContent = 'Copied!';
    } catch {
      const r = document.createRange();
      r.selectNodeContents(content);
      const s = getSelection(); s.removeAllRanges(); s.addRange(r);
      copyBtn.textContent = 'Selected - press Ctrl+C';
    }
    setTimeout(() => copyBtn.textContent = 'Copy text', 1500);
  });

  // ---------- Decoding ----------
  async function handleBlob(blob) {
    const url = URL.createObjectURL(blob);
    preview.src = url;
    try {
      const img = await loadImage(url);
      const text = await decode(img);
      if (text == null) showError('No QR code found. Try a sharper or higher-contrast image.');
      else showResult(text);
    } catch (err) {
      showError('Could not read that image.');
    }
  }

  function loadImage(src) {
    return new Promise((res, rej) => {
      const img = new Image();
      img.onload = () => res(img);
      img.onerror = rej;
      img.src = src;
    });
  }

  function scanAt(img, scale) {
    const w = Math.max(1, Math.round(img.naturalWidth * scale));
    const h = Math.max(1, Math.round(img.naturalHeight * scale));
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    ctx.fillStyle = '#fff';               // handle transparent PNGs
    ctx.fillRect(0, 0, w, h);
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(img, 0, 0, w, h);
    const data = ctx.getImageData(0, 0, w, h);
    const code = jsQR(data.data, w, h, { inversionAttempts: 'attemptBoth' });
    return code ? code.data : null;
  }

  async function decode(img) {
    // Native detector first when available (fast and robust)
    if ('BarcodeDetector' in window) {
      try {
        const det = new BarcodeDetector({ formats: ['qr_code'] });
        const found = await det.detect(img);
        if (found.length) return found[0].rawValue;
      } catch { /* fall through to jsQR */ }
    }
    if (typeof jsQR === 'undefined') throw new Error('jsQR failed to load');

    const maxDim = Math.max(img.naturalWidth, img.naturalHeight);
    const base = maxDim > 1200 ? 1200 / maxDim : 1;
    const scales = [base, base * 0.5, base * 0.25, base * 2].filter(s => s > 0 && s * maxDim <= 3000);
    for (const s of scales) {
      const r = scanAt(img, s);
      if (r != null) return r;
    }
    return null;
  }

  // ---------- Interpretation ----------
  function classify(text) {
    const t = text.trim();
    if (/^https?:\/\//i.test(t)) return { type: 'URL', href: t };
    if (/^mailto:/i.test(t)) return { type: 'Email', href: t };
    if (/^tel:/i.test(t)) return { type: 'Phone', href: t };
    if (/^smsto?:/i.test(t)) return { type: 'SMS', href: t.replace(/^smsto:/i, 'sms:') };
    if (/^geo:/i.test(t)) {
      const m = t.match(/^geo:(-?[\d.]+),(-?[\d.]+)/i);
      return { type: 'Location', href: m ? `https://www.google.com/maps?q=${m[1]},${m[2]}` : null };
    }
    if (/^WIFI:/i.test(t)) return { type: 'Wi-Fi', fields: parseWifi(t) };
    if (/^BEGIN:VCARD/i.test(t)) return { type: 'Contact (vCard)' };
    if (/^BEGIN:VEVENT|^BEGIN:VCALENDAR/i.test(t)) return { type: 'Calendar event' };
    if (/^(javascript|data|vbscript):/i.test(t)) return { type: 'Potentially unsafe', unsafe: true };
    // Bare domain like "example.com/path"
    if (/^(www\.)?[a-z0-9-]+(\.[a-z0-9-]+)+(\/\S*)?$/i.test(t) && !/\s/.test(t))
      return { type: 'URL (no scheme)', href: 'https://' + t };
    return { type: 'Text' };
  }

  function parseWifi(s) {
    const body = s.replace(/^WIFI:/i, '');
    const out = {};
    const parts = body.match(/(?:\\.|[^;])+/g) || [];
    for (const p of parts) {
      const i = p.indexOf(':');
      if (i < 0) continue;
      out[p.slice(0, i)] = p.slice(i + 1).replace(/\\(.)/g, '$1');
    }
    const fields = [];
    if (out.S !== undefined) fields.push(['Network', out.S]);
    if (out.T !== undefined) fields.push(['Security', out.T || 'None']);
    if (out.P !== undefined) fields.push(['Password', out.P]);
    if (out.H !== undefined) fields.push(['Hidden', out.H]);
    return fields;
  }

  // ---------- Rendering ----------
  function showResult(text) {
    currentText = text;
    const info = classify(text);

    result.classList.add('show');
    badge.textContent = info.type;
    badge.className = 'badge ok';
    content.textContent = text;       // textContent => no HTML injection
    copyBtn.style.display = '';

    fieldsEl.replaceChildren();
    if (info.fields?.length) {
      for (const [k, v] of info.fields) {
        const dt = document.createElement('dt'); dt.textContent = k;
        const dd = document.createElement('dd'); dd.textContent = v;
        fieldsEl.append(dt, dd);
      }
    }

    if (info.href) {
      link.href = info.href;
      link.textContent = info.type.startsWith('URL') ? `Open ${info.href}` : `Open (${info.type})`;
      linkWrap.style.display = 'block';
    } else {
      linkWrap.style.display = 'none';
      link.removeAttribute('href');
    }

    if (info.unsafe) {
      warn.textContent = '⚠ This QR code contains a script-style payload. It has been shown as text only and not linked.';
      warn.style.display = 'block';
    } else if (info.href && /^https?:/i.test(info.href)) {
      warn.textContent = 'Only open links from sources you trust.';
      warn.style.display = 'block';
    } else {
      warn.style.display = 'none';
    }
  }

  function showError(msg) {
    currentText = '';
    result.classList.add('show');
    badge.textContent = 'Error';
    badge.className = 'badge err';
    content.textContent = msg;
    fieldsEl.replaceChildren();
    linkWrap.style.display = 'none';
    warn.style.display = 'none';
    copyBtn.style.display = 'none';
  }
})();
</script>
</body>
</html>
```

**How it works**
- **Input:** paste with Ctrl/⌘+V (for example from a screenshot), drag and drop an image, or click to browse.
- **Decoding:** it tries the browser's native `BarcodeDetector` when available, then falls back to jsQR. The fallback retries at several scales and with inverted colors, which helps with large screenshots and light-on-dark codes.
- **Hyperlinks:** `http(s)`, `mailto:`, `tel:`, `sms:`, and `geo:` (opens in a map) payloads get a button. Bare domains like `example.com` are linked with `https://` added. Links open with `rel="noopener noreferrer"`.
- **Other formats:** Wi-Fi QR codes are broken out into network, security and password. vCard and calendar payloads are labeled and shown as raw text.
- **Safety:** decoded content is always inserted with `textContent`, so it can't inject HTML. `javascript:`, `data:` and `vbscript:` payloads are shown as text with a warning and never linked.
- **Privacy:** everything runs in your browser and nothing is uploaded. The only network request is loading the jsQR library from cdnjs.

If your environment blocks external scripts, tell me and I can inline a decoder or rely on `BarcodeDetector` alone, which works in Chromium-based browsers.

