  </div>
  <input type="file" id="file" accept="image/*">

  <section id="result" class="card hidden" aria-live="polite">
    <div class="preview">
      <img id="thumb" alt="Pasted QR code">
      <div style="min-width:0;flex:1">
        <p id="status"></p>
        <span id="type" class="badge hidden"></span>
      </div>
    </div>
    <div id="details"></div>
  </section>
</main>

<script>
(() => {
  const $ = id => document.getElementById(id);
  const drop = $('drop'), fileInput = $('file'), result = $('result');
  const thumb = $('thumb'), statusEl = $('status'), typeEl = $('type'), details = $('details');
  let currentUrl = null;

  // ---------- Input handling ----------
  document.addEventListener('paste', e => {
    const items = e.clipboardData ? [...e.clipboardData.items] : [];
    const item = items.find(i => i.type.startsWith('image/'));
    if (item) { e.preventDefault(); handleBlob(item.getAsFile()); }
    else showError('No image found on the clipboard. Copy the QR code image itself, not a link or text.');
  });

  drop.addEventListener('click', () => fileInput.click());
  drop.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); } });
  fileInput.addEventListener('change', () => { if (fileInput.files[0]) handleBlob(fileInput.files[0]); fileInput.value = ''; });

  ['dragenter', 'dragover'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.add('over'); }));
  ['dragleave', 'drop'].forEach(ev => drop.addEventListener(ev, e => { e.preventDefault(); drop.classList.remove('over'); }));
  drop.addEventListener('drop', e => {
    const f = [...e.dataTransfer.files].find(f => f.type.startsWith('image/'));
    if (f) handleBlob(f); else showError('That doesn’t look like an image file.');
  });

  // ---------- Decoding ----------
  function handleBlob(blob) {
    if (currentUrl) URL.revokeObjectURL(currentUrl);
    currentUrl = URL.createObjectURL(blob);
    const img = new Image();
    img.onload = () => {
      thumb.src = currentUrl;
      const code = decode(img);
      if (code) showResult(code.data); else showError('No QR code found. Try a sharper or larger image, cropped closer to the code.', true);
    };
    img.onerror = () => showError('Could not read that image.');
    img.src = currentUrl;
  }

  function decode(img) {
    if (typeof jsQR !== 'function') return null;
    const maxSide = 1200;
    const base = Math.min(1, maxSide / Math.max(img.naturalWidth, img.naturalHeight));
    // Several passes: screenshots are often cropped with no quiet zone, or too large/small.
    const passes = [
      { scale: base, pad: 40 },
      { scale: base, pad: 0 },
      { scale: base * 0.5, pad: 40 },
      { scale: Math.min(base * 2, 2000 / Math.max(img.naturalWidth, img.naturalHeight)), pad: 40 },
    ];
    for (const { scale, pad } of passes) {
      const w = Math.max(1, Math.round(img.naturalWidth * scale));
      const h = Math.max(1, Math.round(img.naturalHeight * scale));
      const c = document.createElement('canvas');
      c.width = w + pad * 2; c.height = h + pad * 2;
      const ctx = c.getContext('2d', { willReadFrequently: true });
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, c.width, c.height);
      ctx.drawImage(img, pad, pad, w, h);
      const data = ctx.getImageData(0, 0, c.width, c.height);
      const code = jsQR(data.data, c.width, c.height, { inversionAttempts: 'attemptBoth' });
      if (code && code.data) return code;
    }
    return null;
  }

  // ---------- Interpreting the payload ----------
  function classify(text) {
    const t = text.trim();

    if (/^wifi:/i.test(t)) return { type: 'Wi-Fi', wifi: parseWifi(t) };
    if (/^BEGIN:VCARD/i.test(t)) return { type: 'Contact (vCard)' };
    if (/^BEGIN:VEVENT|^BEGIN:VCALENDAR/i.test(t)) return { type: 'Calendar event' };

    const geo = t.match(/^geo:(-?\d+(\.\d+)?),(-?\d+(\.\d+)?)/i);
    if (geo) return { type: 'Location', href: `https://www.openstreetmap.org/?mlat=${geo[1]}&mlon=${geo[3]}#map=16/${geo[1]}/${geo[3]}`, label: 'Open in OpenStreetMap', sub: `${geo[1]}, ${geo[3]}` };

    if (/^(mailto|tel|sms):/i.test(t) && !/\s/.test(t)) {
      const scheme = t.split(':')[0].toLowerCase();
      const names = { mailto: 'Email', tel: 'Phone number', sms: 'SMS' };
      return { type: names[scheme], href: t, label: scheme === 'mailto' ? 'Compose email' : scheme === 'tel' ? 'Call this number' : 'Send text message', sub: t.replace(/^[a-z]+:/i, '') };
    }

    if (/^[a-z][a-z0-9+.-]*:/i.test(t) && !/\s/.test(t)) {
      try {
        const u = new URL(t);
        if (u.protocol === 'http:' || u.protocol === 'https:') return { type: 'URL', href: u.href, label: 'Open link', sub: u.hostname, host: u.hostname, insecure: u.protocol === 'http:' };
        return { type: `${u.protocol.replace(':', '').toUpperCase()} link (not clickable)` };
      } catch {}
    }

    // Bare domains like "www.example.com/path" or "example.org"
    if (!/\s/.test(t) && /^(www\.)?[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}(:\d+)?([/?#]\S*)?$/i.test(t)) {
      try {
        const u = new URL('https://' + t);
        return { type: 'Looks like a URL', href: u.href, label: 'Open link', sub: u.hostname, host: u.hostname, guessed: true };
      } catch {}
    }

    return { type: 'Text' };
  }

  function parseWifi(s) {
    const body = s.replace(/^wifi:/i, '');
    const fields = {};
    let key = '', val = '', inKey = true, esc = false;
    const flush = () => { if (key) fields[key] = val; key = ''; val = ''; inKey = true; };
    for (const ch of body) {
      if (esc) { (inKey ? (key += ch) : (val += ch)); esc = false; }
      else if (ch === '\\') esc = true;
      else if (inKey && ch === ':') inKey = false;
      else if (ch === ';') flush();
      else (inKey ? (key += ch) : (val += ch));
    }
    flush();
    return fields;
  }

  // ---------- Rendering ----------
  function showResult(text) {
    const info = classify(text);
    result.classList.remove('hidden');
    statusEl.className = 'status-ok';
    statusEl.textContent = 'QR code decoded';
    typeEl.textContent = info.type;
    typeEl.classList.remove('hidden');
    details.replaceChildren();

    if (info.href) {
      const a = document.createElement('a');
      a.className = 'link';
      a.href = info.href;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.textContent = info.label;
      const small = document.createElement('small');
      small.textContent = info.sub || info.href;
      a.appendChild(small);
      details.appendChild(a);

      const notes = [];
      if (info.guessed) notes.push('No scheme in the code; assumed https://.');
      if (info.insecure) notes.push('This link uses plain http, which is not encrypted.');
      if (info.host && /(^|\.)xn--/.test(info.host)) notes.push('This domain uses punycode (possible look-alike characters). Double-check it.');
      if (info.host) notes.push('Only open links from QR codes you trust.');
      if (notes.length) details.appendChild(el('p', 'warn', notes.join(' ')));
    }

    if (info.wifi) {
      const dl = document.createElement('dl');
      const w = info.wifi;
      const rows = [['Network', w.S], ['Password', w.P], ['Security', w.T], ['Hidden', w.H]];
      rows.forEach(([k, v]) => { if (v) { dl.appendChild(el('dt', '', k)); dl.appendChild(el('dd', '', v)); } });
      details.appendChild(dl);
    }

    details.appendChild(el('pre', '', text));

    const row = el('div', 'row', '');
    const copy = el('button', '', 'Copy text');
    copy.onclick = async () => {
      try { await navigator.clipboard.writeText(text); copy.textContent = 'Copied ✓'; }
      catch { copy.textContent = 'Copy failed'; }
      setTimeout(() => (copy.textContent = 'Copy text'), 1500);
    };
    row.appendChild(copy);
    details.appendChild(row);
  }

  function showError(msg, keepThumb) {
    result.classList.remove('hidden');
    if (!keepThumb) thumb.removeAttribute('src');
    statusEl.className = 'status-err';
    statusEl.textContent = msg;
    typeEl.classList.add('hidden');
    details.replaceChildren();
  }

  function el(tag, cls, text) {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }
})();
</script>
</body>
</html>
```

**How it works**
- **Input:** paste with Ctrl/⌘+V anywhere on the page. Drag-and-drop and a file picker are there as fallbacks, since some embedded previews restrict clipboard access.
- **Decoding:** it makes several passes at different scales, adds a white border (tightly cropped screenshots often lack the required "quiet zone"), and tries inverted colors.
- **Display:** it shows the raw decoded text and detects the type (URL, email, phone, SMS, geo location, Wi-Fi, vCard, or plain text). Wi-Fi codes are broken out into network, password, and security.
- **Links:** only `http(s)`, `mailto`, `tel`, `sms`, and `geo` payloads become clickable. Anything else, such as `javascript:`, is shown as text only. Links open in a new tab with `noopener`, and there are warnings for plain `http`, punycode look-alike domains, and bare domains where `https://` was assumed.

It needs access to cdnjs to load jsQR. If your environment blocks external scripts, the page will load but won't be able to decode.
